# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
L=[['拉丁 littera／litera','字母；复数也可指书信、文献和学问']]
LET=L+[['古法语 letre → 英语 letter','字母；写成的书信']]
ARY=L+[['拉丁 litterarius → 法语 littéraire','有关文字、文学的'],['英语 literary','文学方面的；带文学色彩的']]
ATE=L+[['拉丁 litteratus → 英语 literate','受过文字教育的 → 会读写的、有相应素养的']]
ILL=L+[['拉丁 in- + litteratus → illitteratus','没有受过文字教育的；in- 在 l 前同化为 il-'],['英语 illiterate','不会读写的；对某领域缺乏基本知识的']]
ACY=ATE+[['英语 literate 对应的名词 literacy','读写能力；某方面的素养']]
def H(h,w,m):return h+[[w,m]]
WA=[
E('letter','英 /ˈletə/；美 /ˈletər/','字母；信；按字面写出的条文；写上字母','一个个字母排在一起，就能把想告诉对方的话装进一封信。','拉丁 littera 经古法语 letre 进入英语；letter 的两个常用名词义在这条历史路线中相连。',LET,'a letter 可以是 A、B 这样的一个字母，也可以是一整封信。to the letter 则是“连字面细节都照做”，如严格按说明操作。作动词时可指给牌子写字。另有罕见 letter“出租者”，来自 let + -er，与本页不同源。','a letter of thanks；capital letters；follow the instructions to the letter。','letter 是字母或书信；word 是由字母组成的词。字面条文叫 the letter，条文背后的用意常叫 the spirit。',('Write your name in capital letters.','请用大写字母写下你的名字。'),('I found a letter from my grandmother inside the book.','我在书里发现了一封奶奶写的信。'),('She followed the instructions to the letter.','她一丝不差地按说明操作。'),sources=['https://www.etymonline.com/word/letter','https://en.wiktionary.org/wiki/letter']),
E('literature','英 /ˈlɪtrətʃə/；美 /ˈlɪtərətʃər/','文学；文学作品；某领域的文献；介绍资料','把文字写成、积累成一批作品或资料，这批文字就可以成为 literature。','接拉丁 litteratura／literatura“文字学习、书写、学问”，与 littera 同源；中古英语中已有 literature。',L+[['拉丁 litteratura → 中古英语 literature','文字学习、书本学问'],['现代英语 literature','文学作品；某主题的文献或资料']],'读 English literature，多半在读英语文学；做 a literature review，是梳理某个研究问题已有的文献；展台上的 product literature 则可能只是产品介绍册。共同点是“某一类成体系的文字材料”，并非出现这个词就一定在谈小说。','study literature；a review of the literature；scientific literature；product literature。','literature 通常是不可数名词，说 three works of literature，不通常说 three literatures 来数三本书。literary 是相应的形容词，但有自己的法语、拉丁语借入路线。',('She enjoys literature that explores ordinary family life.','她喜欢描写普通家庭生活的文学作品。'),('Before starting the study, we reviewed the literature on the topic.','开始研究前，我们梳理了这一主题的已有文献。'),sources=['https://www.etymonline.com/word/literature','https://en.wiktionary.org/wiki/literature']),
E('literary','英 /ˈlɪtərəri/；美 /ˈlɪtəˌreri/','文学的；文坛的；带书面文学色彩的','文字不只用来交代事情，还被当作作品来经营、欣赏和研究。','来自法语 littéraire，接拉丁 litterarius“与文字、文学有关的”；不是把英语 literature 简单截短再加 -ary 的历史。',ARY,'a literary prize 是文学奖；a literary critic 是文学评论家；a literary expression 是平时聊天少说、作品里较常见的表达。它说的是与文学的关系或语言风格，不能直接翻成“会读写的”。','literary fiction；a literary magazine；literary criticism；a literary style。','literary 关乎文学；literate 关乎读写能力或某领域素养；literal 关乎字面意思。三者的重点不同。',('The journal publishes literary essays and short stories.','这本期刊刊登文学随笔和短篇小说。'),('That expression sounds literary rather than conversational.','那个表达带有文学色彩，日常聊天不太这样说。'),sources=['https://www.etymonline.com/word/literary','https://en.wiktionary.org/wiki/literary']),
E('literariness','英 /ˈlɪtərərinəs/；美 /ˈlɪtəˌrerinəs/','文学性；文学修养〔较书面〕','问一段文字“哪里让人感觉它像文学作品”，讨论的就是它的文学性。','literary 的 y 变 i + -ness，把文学方面的性质变成名词。',H(ARY,'英语 literary → literariness','文学的 → 文学性、文学修养'),'写事实也能有文学性：节奏、意象、叙述角度都可能让文字超出单纯报信息。literariness 也可形容一个人熟悉文学的程度。它不等于词语越生僻越好，也没有一把人人公认的量尺。','the literariness of a text；a discussion of literariness。','literature 是作品或作品领域；literariness 是这些文字呈现出的文学特质。',('The class discussed the literariness of an ordinary diary entry.','全班讨论了一则普通日记具有什么文学性。'),('The reviewer admired the literariness of her prose.','评论者赞赏她散文的文学韵味。'),sources=['https://en.wiktionary.org/wiki/literariness','https://www.etymonline.com/word/literary']),
E('literate','/ˈlɪtərət/','会读写的；有文化修养的；具备某方面基本素养的','眼前的字不再只是符号：你能读懂，也能用它们把自己的意思写出来。','拉丁 litteratus“受过文字教育的”，经中古英语进入现代英语；词尾 -ate 在这个形容词里读 /ət/。',ATE,'最基本的 literate 是会阅读和书写。computer literate 则把画面扩展成“看得懂、用得来计算机”；financially literate 指能理解相关基本信息。要看前面的限定词，不能把所有 literate 都译成“文学的”。','be literate；computer literate；scientifically literate。','literate 是能力或素养；literary 是文学相关；literal 是照字面。会读写不等于必须精通文学研究。',('The course helps adults become literate in their first language.','这门课程帮助成年人学会用母语读写。'),('The job requires staff to be computer literate.','这项工作要求员工具备基本的计算机使用能力。'),sources=['https://www.etymonline.com/word/literate','https://en.wiktionary.org/wiki/literate']),
E('illiterate','/ɪˈlɪtərət/','不会读写的；缺乏某方面基本知识的','面对文字，缺少把它读懂或写出来的能力；加上领域名后，也可说对那一行不熟。','拉丁否定前缀 in- 在 l 前变为 il-，与 litteratus 构成 illitteratus；英语借入为 illiterate。',ILL,'illiterate 最常说读写能力不足，computer illiterate 则说不懂电脑。它还可能批评文字不合规范，语气往往不客气。描述具体困难时，说 someone cannot read 比把整个人贴成“文盲”通常更清楚，也不会把读写能力误当成智力。','illiterate adults；remain illiterate；computer illiterate。','illiterate 不等于 unintelligent。阅读能力也有程度差别，不是所有困难都能压成“会”或“不会”两格。',('He was illiterate until he joined an adult reading class.','直到参加成人识字班之前，他一直不会读写。'),('I used to be computer illiterate, but I can now manage the website.','我以前不懂电脑，现在已经能管理这个网站了。'),sources=['https://www.etymonline.com/word/illiterate','https://en.wiktionary.org/wiki/illiterate']),
E('literacy','/ˈlɪtərəsi/','读写能力；识字能力；某领域的素养','不是只认出几个字母，而是能从文字中获取意思，也能把意思写给别人。','literate 对应的 -cy 名词形式，书写上成为 literacy；英语记录中它比 illiteracy 更晚出现。',ACY,'成人 literacy 课程常教实际生活中的阅读和书写，如读通知、填表格。media literacy 把这个想法扩展到媒体：能理解信息，也能判断它靠不靠谱。具体达到什么水平，要看课程或研究如何界定。','improve literacy；adult literacy；digital literacy；media literacy。','literacy 是能力，literature 是作品与文献。不能只按现代外形，就说历史上先有 literacy、再给它加 il- 得到 illiteracy。',('The library offers free classes to improve adult literacy.','图书馆开设免费课程，帮助成年人提高读写能力。'),('Media literacy helps students question misleading headlines.','媒体素养帮助学生识别和质疑误导性的标题。'),sources=['https://www.etymonline.com/word/literacy','https://en.wiktionary.org/wiki/literacy']),
E('illiteracy','/ɪˈlɪtərəsi/','不会读写的状态；识字教育不足的问题','把一个人的读写困难，或一群人面临的识字问题，作为一件事来讨论。','历史上由 illiterate 与 -cy 构成。今天可看出 il- 和 literacy 的对照，但英语 illiteracy 的记录早于 literacy。',H(ILL,'英语 illiterate + -cy → illiteracy','不会读写的 → 不会读写的状态'),'reduce illiteracy 是让更多人获得读写能力；an illiteracy rate 是按某套标准统计的不会读写人口比例。讨论这个问题时，教育机会和语言环境都重要，不能把统计数字理解成一群人的聪明程度。','adult illiteracy；reduce illiteracy；the rate of illiteracy。','illiterate 是形容一个人或状态的词；illiteracy 把这种状态名词化。它的历史不是简单在后来出现的 literacy 前加 il-。',('The programme aims to reduce illiteracy in the community.','这个项目旨在减少社区中的读写困难。'),('The report explains how illiteracy was measured.','报告解释了不会读写这一状态是按什么标准衡量的。'),sources=['https://www.etymonline.com/word/illiteracy','https://www.etymonline.com/word/literacy']),
E('illiterately','/ɪˈlɪtərətli/','不合文字规范地；显得缺乏文字修养地〔少见，常带批评〕','评语的矛头落在“这段话怎么写的”：句法、用字让评论者觉得不够规范。','illiterate + -ly，说明写作或表达的方式。',H(ILL,'英语 illiterate → illiterately','不合文字规范的 → 以这种方式表达'),'illiterately written 通常不是说作者完全不会写字，而是在严厉批评作品里的语法或用字。这个副词少见，而且评价色彩强；如果只想指出拼写错误，直接说 badly spelled 会更具体。','illiterately written；write illiterately。','illiterately 是对表达方式的评价；incorrectly 只是说某处不正确，未必连带评价作者的文化修养。',('The critic described the notice as illiterately written.','评论者批评这则通知写得很不规范。'),('The editor said the sentence was illiterately phrased and suggested a revision.','编辑认为这句话措辞不规范，并提出了修改意见。'),sources=['https://en.wiktionary.org/wiki/illiterately','https://www.merriam-webster.com/dictionary/illiterate']),
E('lettered','英 /ˈletəd/；美 /ˈletərd/','写有字的；有学问的、受过良好文字教育的','物上“有字”，人心里“有书本学问”，同一个词沿这两种画面使用。','letter + -ed；既可接“给东西写字”的动作，也可表示具备文字教育的性质。',H(LET,'英语 letter → lettered','写上字 → 有字的；有文字修养的'),'a lettered sign 是写着文字的牌子；a lettered scholar 是有学问的学者。前者看表面有什么，后者看人读过、掌握过什么。形容人的这个义较书面，不能把所有 lettered 都理解成收到了一封信。','a beautifully lettered sign；a lettered scholar；lettered in gold。','lettered 的学识义接近 learned；literate 更常说基本读写能力。二者有重叠，但使用语气不同。',('The wooden sign was lettered in white paint.','木牌上的字是用白漆写的。'),('The essay portrays her as a widely travelled and lettered woman.','这篇随笔把她描写成一位见多识广、富有学识的女性。'),sources=['https://en.wiktionary.org/wiki/lettered','https://www.etymonline.com/word/letter']),
E('unlettered','英 /ʌnˈletəd/；美 /ʌnˈletərd/','未受文字教育的；不识字的；没有书本学问的〔书面〕','生活中可能很有经验，却没有机会进入读书、写字的世界。','un-“没有” + lettered“受过文字教育的”。',H(LET,'英语 lettered → unlettered','有文字修养的 → 未受文字教育的'),'旧文章里的 an unlettered person 常指没受过学校或读写教育的人。它不自动说明这个人没有判断力、手艺或口头知识。这个词带有书面、旧式色彩，现代叙述可更具体地说明缺少哪种教育。','an unlettered audience；remain unlettered。','unlettered 强调缺少文字教育或书本修养；uneducated 的范围可能更广，也不能等同于没有生活智慧。',('The tale was passed down by people the old writer called unlettered.','这个故事由那位旧时作者称为“未受文字教育”的人们传承下来。'),('Though unlettered, she could explain the history of every house in the village.','她虽不识字，却能讲清村里每一栋房子的历史。'),sources=['https://en.wiktionary.org/wiki/unlettered','https://www.etymonline.com/word/lettered']),
E('preliterate','/priːˈlɪtərət/','尚未学会读写的；文字使用之前的','把时间线停在学会读写之前，或某种文化开始使用文字之前。','pre-“在……之前” + literate。',H(ATE,'英语 pre- + literate → preliterate','读写的 → 进入读写阶段之前的'),'a preliterate child 已经可能会说故事、认图画，只是尚未学会读写。历史或人类学里的 preliterate culture 指文字使用以前的文化，不是说它没有语言、思想或复杂知识。这个词强调阶段。','preliterate children；a preliterate society；preliterate storytelling。','preliterate 强调“之前”；nonliterate 说明未使用文字或不具备读写能力，并不一定预测未来会沿同一条发展路线变化。',('Picture books can engage preliterate children.','图画书也能吸引尚未学会读写的孩子。'),('The lecture examined how knowledge was preserved in preliterate communities.','讲座讨论了文字使用之前的群体怎样保存知识。'),sources=['https://en.wiktionary.org/wiki/preliterate','https://www.merriam-webster.com/dictionary/preliterate']),
E('nonliterate','/nɒnˈlɪtərət/','不会读写的；不以文字为主要记录方式的','信息主要靠口述、记忆和其他方式传递，而不是靠读写文本。','non-“不具备” + literate。',H(ATE,'英语 non- + literate → nonliterate','具备读写能力的 → 不具备读写能力的、非文字的'),'用于个人时，nonliterate 常与不会读写有关；用于文化或传统时，重点可能是没有采用文字记录。要看句子在谈人的能力还是群体的记录方式，不能一概理解成没有文化。','nonliterate adults；nonliterate traditions；a nonliterate community。','nonliterate 与 illiterate 有重叠；前者在文化研究里常用来描述文字使用状况，后者在日常语境里更容易成为能力评价。',('The instructions include pictures for nonliterate users.','说明配有图画，方便不会读写的使用者理解。'),('Researchers studied storytelling in a nonliterate community.','研究者考察了一个不使用文字的群体如何讲述和传承故事。'),sources=['https://en.wiktionary.org/wiki/nonliterate','https://www.merriam-webster.com/dictionary/nonliterate']),
]
